<script setup lang="ts">
import {ref,reactive,computed,onMounted,onUnmounted} from 'vue';
import {createStatusReader} from './statusReader.mjs';
import {createConnectionCheckSender,newerConnectionCheck,checkStateLabels,checkStageLabels,checkPartLabel} from './connectionCheck.mjs';
import {createEquityEditor,emptyEquityEdits} from './equityEditor.mjs';
const authorDialog=ref<HTMLDialogElement|null>(null);
const equityEdits=reactive<any>(emptyEquityEdits());
const equityEditor=createEquityEditor({states:equityEdits,storage:{getItem:(k:string)=>localStorage.getItem(k),setItem:(k:string,v:string)=>localStorage.setItem(k,v),removeItem:(k:string)=>localStorage.removeItem(k)}});
const snapshot=ref<any>(null),tab=ref('总览'),notice=ref(''),error=ref(''),busy=ref(false),online=ref(false);
const symbols=['BTCUSDT','ETHUSDT'];let timer:any;
const statusReader=createStatusReader();
const checkSender=createConnectionCheckSender(),checkSubmitting=ref(false),checkNotice=ref(''),checkError=ref('');
const connectionCheck=computed(()=>snapshot.value?.connection_check||worker.value.connection_check||{});
const checkState=computed(()=>(checkStateLabels as any)[connectionCheck.value.state]||'尚未发起人工检查');
const checkStage=computed(()=>(checkStageLabels as any)[connectionCheck.value.stage]||connectionCheck.value.stage||'—');
const displayStream=computed(()=>snapshot.value?.market_stream||{});
const streamSummary=computed(()=>displayStream.value.display_copy_stale?'显示副本已过期，等待下一次读取':displayStream.value.connections?.public&&displayStream.value.connections?.market?'两条行情通道已连接':'行情通道待恢复');
const account=computed(()=>snapshot.value?.account||{});
const worker=computed(()=>snapshot.value?.strategy==='HourlyTrendRange'?(snapshot.value.worker||{}):{});
const desiredRunning=computed(()=>worker.value.desired_running===true||snapshot.value?.desired_running===true);
const startReady=computed(()=>!!snapshot.value?.updated_at&&((account.value.connected&&blockers.value.length===0)||snapshot.value?.deferred_start_available===true));
const recovery=computed(()=>worker.value.execution_recovery||{});
const recoveryName=computed(()=>({local_budget_wait:'本地读取额度等待',exchange_cooldown:'交易所限流等待',network_read_failure:'网络连接重试',network_read_wait:'网络重试等待',timestamp_rejected:'时间同步恢复',order_uncertain:'查询原订单',credentials_error:'账户授权待恢复',restart_reconciliation:'进程恢复核对',symbol_activation:'新增品种核对',execution_review:'执行状态核对',permanent:'配置或读取问题核对',exchange_rejected:'交易所拒绝原因核对'} as any)[recovery.value.kind]||'自动核对恢复');
const networkRetry=computed(()=>snapshot.value?.network_retry||worker.value.network_retry||{});
const streamRetries=computed(()=>[['执行引擎',snapshot.value?.market_stream]].flatMap(([label,source]:any)=>Object.entries(source?.retry||{}).filter(([,retry]:any)=>retry.waiting).map(([channel,retry]:any)=>({name:`${label} ${channel==='public'?'买卖报价':'成交与标记价格'}`,seconds:Math.max(0,Math.ceil(Number(retry.retry_in_seconds)||0))}))));
const old=computed(()=>snapshot.value?.legacy_worker||(snapshot.value?.worker?.strategy&&snapshot.value.worker.strategy!=='HourlyTrendRange'?snapshot.value.worker:{}));
const migration=computed(()=>snapshot.value?.migration||{required:true,blockers:['新控制台接口尚未就绪，请等待部署并刷新']});
const blockers=computed(()=>snapshot.value?.strategy==='HourlyTrendRange'?(snapshot.value?.blockers||[]):['新控制台接口尚未就绪，请等待部署并刷新']);
const running=computed(()=>online.value&&worker.value.connected&&worker.value.state==='running');
const symbolChoice=computed(()=>{const source=worker.value.connected?worker.value.symbol_enabled:snapshot.value?.trade_controls?.symbols;return {BTCUSDT:source?.BTCUSDT===true,ETHUSDT:source?.ETHUSDT===true};});
const selectedCount=computed(()=>Object.values(symbolChoice.value).filter(Boolean).length);
const newApi=computed(()=>snapshot.value?.strategy==='HourlyTrendRange');
const ledgerMismatch=computed(()=>account.value.connected&&!(account.value.positions||[]).length&&account.value.open_orders===0&&account.value.open_algo_orders===0&&snapshot.value?.legacy_book?.open_trades>0);
const oldPresent=computed(()=>old.value.connected||old.value.process_alive||snapshot.value?.legacy_book?.open_trades>0);
const pauseConfirmed=computed(()=>online.value&&newApi.value&&((worker.value.connected&&!desiredRunning.value&&['paused','stopped'].includes(worker.value.state))||(!worker.value.connected&&worker.value.state==='stopped'&&!worker.value.process_alive&&!!snapshot.value?.updated_at)));
const pauseButtonDone=computed(()=>pauseConfirmed.value&&(worker.value.state==='paused'||(!(worker.value.trades||[]).length&&!(worker.value.unknown_orders||[]).length)));
const stateLabel=computed(()=>!online.value?'控制状态待重新连接':migration.value.required?'新策略待过渡':!worker.value.connected?(worker.value.state==='unknown'?'引擎状态待核对':'已停止新开仓 · 引擎未启动'):({running:selectedCount.value?'所选品种允许新开仓':'全部品种新开仓已关闭',paused:'已停止新开仓',stopped:'已停止新开仓',waiting:desiredRunning.value?'自动交易已启用 · 等待恢复':'读取等待 · 新开仓已停止',recovering:desiredRunning.value?'自动交易已启用 · 正在核对恢复':'执行核对中 · 新开仓已停止',fault:desiredRunning.value?'自动交易已启用 · 异常处理中':'执行异常 · 新开仓已停止'} as any)[worker.value.state]||'状态待核对');
const oldLabel=computed(()=>old.value.state==='running'?(old.value.max_open_trades===0?'已暂停新仓，继续管理旧仓':'旧策略仍在运行'):old.value.state==='paused'?'已暂停新仓，继续管理旧仓':old.value.state==='stopped'?'旧引擎已停止':'旧引擎状态待核对');
const f=(v:any,d=2)=>v===undefined||v===null||v===''?'—':Number(v).toLocaleString('zh-CN',{maximumFractionDigits:d,minimumFractionDigits:d});
const eventTime=(e:any)=>e.time_ms?new Date(Number(e.time_ms)).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):(e.time||e.timestamp||'—');
const closedTime=(value:any)=>value?new Date(value).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'—';
const direction=(v:any)=>Number(v)===1?'做多':Number(v)===-1?'做空':'无入场信号';
const oldExitReason=(value:any)=>value==='external_exit_reconciled'?'交易所外部平仓已核对':value||'旧引擎持仓中';
function liveQuote(symbol:string){const data=displayStream.value.symbols?.[symbol];return data?.trade_live===true&&data?.freshness?.trade?.available!==false?data.latest_trade?.price:undefined;}
function quoteStatus(symbol:string,kind:string){const source=displayStream.value.symbols?.[symbol]||{},detail=source.freshness?.[kind]||{};return detail.display_copy_expired?'显示副本过期':source[kind+'_live']===true?'数据新鲜':detail.reason==='no_message'?'等待行情消息':'数据待更新';}
function market(symbol:string){return snapshot.value?.strategy==='HourlyTrendRange'?(snapshot.value?.markets?.[symbol]||{}):{};}
function spark(symbol:string){const c=market(symbol).candles||[];if(c.length<2)return '';const vals=c.map((r:any)=>r.close),lo=Math.min(...vals),hi=Math.max(...vals);return vals.map((v:number,i:number)=>`${i/(vals.length-1)*600},${115-(v-lo)/(hi-lo||1)*100}`).join(' ');}
async function api(path:string,method='GET',body?:any){const r=await fetch('/api/'+path,{method,headers:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});const d=await r.json();if(!r.ok)throw Error(d.detail||d.error||'请求失败');return d;}
async function refresh(){await statusReader.read(()=>api('status'),(value:any)=>{snapshot.value=value;online.value=true;if(error.value.startsWith('控制台连接中断'))error.value='';},()=>{online.value=false;error.value='控制台连接中断；当前显示最后一次读取结果，请等待重新连接。';});}
async function checkConnection(){if(checkSubmitting.value)return;checkSubmitting.value=true;checkNotice.value='';checkError.value='';try{const result:any=await checkSender.send(async(signal:AbortSignal)=>{const response=await fetch('/api/check-connection',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({confirmed:true}),signal});const data=await response.json();if(!response.ok)throw Error(data.detail||'连接检查尚未受理');if(data.ok!==true||!data.connection_check?.id)throw Error('检查任务未确认，请查看任务状态。');return data;});snapshot.value={...snapshot.value,connection_check:newerConnectionCheck(connectionCheck.value,result.connection_check)};checkNotice.value=result.message||'连接检查已登记，受理不代表成功；请查看进度。';await refresh();}catch(e:any){checkError.value=e.message||'检查任务受理结果尚未确认，请查看任务状态。';}finally{checkSubmitting.value=false;}}
function applyControlReply(reply:any){if(reply.worker)snapshot.value={...snapshot.value,worker:reply.worker,control_revision:reply.control_revision,worker_updated_at:reply.worker_updated_at};}
async function setSymbol(symbol:string){const next={...symbolChoice.value,[symbol]:!symbolChoice.value[symbol as 'BTCUSDT'|'ETHUSDT']};const enable=next[symbol as 'BTCUSDT'|'ETHUSDT'];const text=enable?`启用${symbol}的新开仓？首次选择后需启动策略。策略已启用时，新增品种会自动核对设置后继续，已有持仓继续保护和退出。`:`停止${symbol}的新开仓？已有该品种持仓继续按止损和退出规则管理，不会立即平仓。`;busy.value=true;statusReader.invalidate();error.value='';notice.value='';try{const r=await api('symbols','POST',{confirmed:true,symbols:next});applyControlReply(r);notice.value=r.message||'品种选择已提交，请核对显示状态';await refresh();}catch(e:any){error.value=e.message;}finally{busy.value=false;}}
async function action(name:string){if(name==='start'&&!selectedCount.value){error.value='先手动启用BTC或ETH，至少选择一个品种。';return;}const selected=Object.entries(symbolChoice.value).filter(([,enabled])=>enabled).map(([symbol])=>symbol).join('、');const messages:any={start:`启动所选品种${selected}的小时策略？使用50倍全仓，按入场权益50%计划止损预算与15倍权益名义上限计算数量，满足信号时发送真实市价订单。`,pause:'停止新小时策略全部新开仓？已有持仓继续止损和退出管理，不会立即平仓。','exit-all':'请求平掉新策略登记的全部持仓并暂停新开仓？提交后请核对实际成交。',restore:'恢复新小时引擎读取原实盘账本并核对仓位和订单？沿用已保存的启停意图；开启意图经核对后自动继续。','legacy-pause':'停止旧策略的新开仓？已有旧持仓继续由旧引擎管理止损和退出，不会立即平仓。','legacy-exit-all':'请求旧引擎平掉其登记的全部持仓并暂停新开仓？这是实盘市价退出，请等待实际成交确认。',migrate:'应用唯一的新固定小时策略？系统重新核对全账户无持仓、无普通及条件单、旧账本无未平交易后退出旧引擎。原账本和损益记录保留，新引擎尚不启动。'};if(!messages[name])return;if(['start','exit-all'].includes(name)&&!confirm(messages[name]))return;busy.value=true;statusReader.invalidate();error.value='';notice.value='';try{const body:any={confirmed:true};if(name==='start')body.symbols={...symbolChoice.value};const r=await api(name,'POST',body);applyControlReply(r);notice.value=r.message||'操作已提交，请核对实际状态';await refresh();}catch(e:any){error.value=e.message;}finally{busy.value=false;}}
const fixedRows=[['交易品种','BTCUSDT、ETHUSDT 永续；分别手动启用'],['账户模式','USDT单资产 · 单向持仓 · 50倍全仓'],['独立资金','每品种默认100 USDT，可分别调整当前策略权益，之后继续记盈亏、费用和资金费；币安实际全仓保证金共享'],['信号与执行','1小时信号，边界对应5分钟线执行'],['市场分支','Wilder ADX14 ≥20趋势突破；<20震荡回归'],['趋势入场','EMA50方向过滤＋此前12根小时高低价严格突破'],['趋势退出','多头收盘<EMA12；空头收盘>EMA12'],['震荡入场','SMA30 ± 1.5倍总体标准差；RSI14多<45、空>55；距中轨/收盘严格>.2%'],['震荡退出','多头收盘>SMA30；空头收盘<SMA30'],['分支冻结','每笔保存入场分支，ADX变化不改变退出规则'],['波动率','Wilder ATR14'],['初始止损','实际均价±5×入场信号ATR快照；只收紧'],['追踪止损','合格完整小时累计极值±6×当前ATR；排除首次成交所在小时'],['计划预算','冻结入场前本品种账本标记价权益的50%'],['名义上限','冻结本品种权益的15倍'],['数量和保证金','向下取整；初始保证金+开仓费≤95%E₀；另检查真实可用保证金'],['入场窗口','小时边界起[0,5分钟)，过时作废；每个信号一次'],['预热','1,000根完整小时线，预热不交易'],['持仓限制','每品种一笔，禁止加仓、补仓、马丁'],['预计成本','每边手续费.05%、不利滑点.02%'],['资金费','实际结算分别进入本品种权益，不预估未来资金费用于开仓'],['止盈 / 冷却 / 统计停机','均不设；技术异常自动处理，核对恢复后自动继续']];
const apiKey=ref(''),apiSecret=ref('');
function branch(v:any){return v==='trend'?'趋势突破':v==='range'?'震荡回归':'—';}
function ledger(s:string){return worker.value.strategy_ledgers?.[s]||{};}
async function equityRequest(path:string,body?:any){const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),50000);try{const r=await fetch('/api/'+path,{method:body?'POST':'GET',headers:{'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined,signal:controller.signal});const result=await r.json();if(!r.ok){const e:any=new Error(result.detail||'保存请求尚未确认');e.definite=[400,401,403,404,409,422].includes(r.status);throw e;}return result;}finally{clearTimeout(timeout);}}
async function saveEquity(s:string){await equityEditor.save(s,(body:any)=>equityRequest('strategy-equity',body));await refresh();}
async function queryEquity(s:string){await equityEditor.query(s,(id:string)=>equityRequest('strategy-equity/'+id));await refresh();}
function eventText(e:any){const d=e.details||{};return [e.message||e.reason||e.type,d.symbol,d.reason||d.skip_reason,d.branch?branch(d.branch):''].filter(Boolean).join(' · ');}
function entryReason(s:string){const m=market(s);if(!symbolChoice.value[s as 'BTCUSDT'|'ETHUSDT'])return '此品种新开仓已关闭';if(!running.value)return '新开仓尚未启动';if(!m.ready)return '等待1,000根完整小时线预热';if(!m.direction)return `${branch(m.branch)}条件未同时满足，等待下一小时收盘`;if(!m.signal_valid_now)return '信号窗口已结束，等待下一小时收盘';return '本小时存在信号，执行结果请查看运行事件';}
async function setupCredentials(){busy.value=true;statusReader.invalidate();error.value='';try{const r=await api('setup','POST',{confirmed:true,api_key:apiKey.value,api_secret:apiSecret.value});apiKey.value='';apiSecret.value='';notice.value=r.message;await refresh();}catch(e:any){error.value=e.message;}finally{busy.value=false;}}

onMounted(()=>{authorDialog.value?.showModal();refresh();timer=setInterval(()=>{if(!busy.value)refresh();},5000);});onUnmounted(()=>{clearInterval(timer);statusReader.invalidate();});
</script>
<template>
<div class="shell">
  <aside class="sidebar"><div class="brand"><span class="mark">Q</span><div>合约交易台<small>BTC / ETH · 趋势与震荡</small></div></div><div class="nav-label">工作台</div><button v-for="(name,i) in ['总览','交易记录','固定参数','策略说明']" :class="['nav',tab===name?'selected':'']" @click="tab=name"><span>{{['◈','≡','⚙','⌘'][i]}}</span>{{name}}</button><div class="side-bottom"><span class="live-dot"></span>币安 U 本位 · 实盘<small>EMA50 / 12小时突破<br>中文交易台 3.1 · 自动恢复</small></div></aside>
  <main>
    <header><div><div class="eyebrow">固定小时策略 / 实盘账户</div><h1>{{tab==='总览'?'交易总览':tab}}</h1><p>ADX14分支 · EMA50 / EMA12 · 布林回归 · Wilder ATR14保护</p></div><div class="header-status"><span :class="['badge',account.connected&&online?'good':'muted']">{{!online?'控制台离线':account.connected?'账户已连接':'账户未连接'}}</span><span :class="['badge',running?'good':'muted']">{{stateLabel}}</span></div></header>
    <div v-if="error" class="alert danger">{{error}}</div><div v-if="notice" class="alert success">{{notice}}</div><div v-if="account.error&&!snapshot?.setup_required" class="alert danger">{{account.error}}</div>
    <section v-if="tab==='总览'" class="panel"><div class="panel-heading"><h2>连接与请求状态</h2><span class="version">{{worker.software_release||'等待执行引擎'}}</span></div><p class="small-note">当前分钟 IP 已用权重 {{snapshot?.request_budget?.used_weight??'—'}} / 本地普通读取额度 {{snapshot?.request_budget?.read_budget_per_minute??'—'}}；最近一小时本安装预留峰值 {{snapshot?.request_budget?.reserved_peak_weight_last_hour??'—'}}。<br>账户显示来源：{{account.source==='worker_reconcile'?'执行引擎完整核对':account.source==='console_cached'?'监控读取缓存':'币安账户读取'}}；数据年龄 {{f(account.age_seconds,1)}} 秒。实时行情优先使用 WebSocket。</p><details v-if="snapshot?.request_budget?.current_endpoint_usage?.length"><summary>查看当前分钟接口用量</summary><ul><li v-for="usage in snapshot.request_budget.current_endpoint_usage">{{usage.method}} {{usage.endpoint}}：{{usage.calls}} 次，预留权重 {{usage.reserved_weight}}</li></ul></details></section>
    <section v-if="snapshot?.setup_required" class="panel setup-panel"><div class="panel-heading"><h2>首次配置此安装</h2><span class="version">空白配置 · 实盘接口</span></div><p class="intro">填写自己的币安合约API，保存后等待账户连接，再手动选择品种并启动。</p><form @submit.prevent="setupCredentials"><label>API Key<input v-model="apiKey" type="password" autocomplete="off" required></label><label>API Secret<input v-model="apiSecret" type="password" autocomplete="off" required></label><button class="primary" :disabled="busy||!online">保存本地配置</button></form></section>
    <section class="panel trade-controls"><div class="panel-heading"><h2>交易操作</h2><span class="version">{{stateLabel}}</span></div><p class="intro">BTC与ETH分别选择是否交易。首次选择后点击启动；随后技术异常由软件分类处理，核对恢复后自动继续。运行中新增品种会自动核对。你主动停止的策略或品种保持停止；已有持仓继续保护和退出。</p><div class="symbol-controls"><article v-for="symbol in symbols" class="symbol-control"><div><h3>{{symbol}}</h3><span :class="['badge',symbolChoice[symbol as 'BTCUSDT'|'ETHUSDT']&&running?'good':'muted']">{{symbolChoice[symbol as 'BTCUSDT'|'ETHUSDT']?(running?'已允许新开仓':pauseConfirmed?'已选择 · 新开仓已停止':desiredRunning?'已启用 · 自动恢复中':'已选择 · 等待启动'):'新开仓已关闭'}}</span></div><button :class="symbolChoice[symbol as 'BTCUSDT'|'ETHUSDT']?'stop-button':'secondary'" @click="setSymbol(symbol)" :disabled="busy||!online||!newApi">{{symbolChoice[symbol as 'BTCUSDT'|'ETHUSDT']?'停止':'启用'}}{{symbol.startsWith('BTC')?'BTC':'ETH'}}新开仓</button></article></div><div class="control-actions"><button class="primary" @click="action('start')" :disabled="busy||!online||!startReady||running||desiredRunning||!selectedCount">{{busy?'处理中…':running?'新策略正在运行':desiredRunning?'自动交易已启用 · 等待恢复':'启动所选品种实盘交易'}}</button><button class="stop-button" @click="action('pause')" :disabled="busy||!online||!newApi||pauseButtonDone">{{pauseButtonDone?'已停止新开仓':'停止全部新开仓'}}</button><button v-if="oldPresent||old.connected" class="stop-button" @click="action('legacy-pause')" :disabled="busy||!online||!old.connected">停止旧策略新开仓</button></div><div v-if="pauseConfirmed" class="entry-stopped" role="status"><strong>已停止全部新开仓</strong><span>引擎已确认停止。行情和账户核对继续更新；已有持仓继续执行保护与退出。</span><small v-if="snapshot?.worker_updated_at">控制状态确认：{{snapshot.worker_updated_at}}</small></div><p class="control-caption">停止新开仓后，已有持仓继续止损和退出；不会立即平仓。要立即请求平仓，请使用“交易记录”的平仓按钮，或下面旧持仓过渡中的平仓按钮。</p><p v-if="!worker.connected&&!old.connected" class="small-note">目前没有已连接的交易引擎。点击“停止全部新开仓”会核对新引擎是否已经停止；若进程状态未知则提示待核对。账本未平记录不等于交易进程正在运行。</p><p v-if="!selectedCount" class="small-note">尚未启用品种。请先点击“启用BTC新开仓”或“启用ETH新开仓”，再启动。</p></section>
    <section v-if="false" class="panel legacy-review"><div class="panel-heading"><h2>旧持仓过渡</h2><span class="version">{{oldLabel}}</span></div><p>新页面仅提供你指定的固定小时策略。{{old.connected?'旧引擎仍负责其登记持仓，新策略尚未迁移。':old.process_alive?'旧进程存在但接口状态待核对，新策略尚未迁移。':'旧交易进程未连接，正在核对原账本记录与交易所状态。'}}</p><p>旧引擎登记 {{old.connected?(old.trades||[]).length:f(snapshot?.legacy_book?.open_trades,0)}} 笔持仓；账户实际持仓 {{account.connected?(account.positions||[]).length:'—'}} 笔，普通订单 {{account.connected?account.open_orders:'—'}} 笔，条件单 {{account.connected?account.open_algo_orders:'—'}} 笔。</p><div class="transition-actions"><button class="secondary" @click="action('legacy-pause')" :disabled="busy||!online||!old.connected">停止旧策略新开仓</button><button class="secondary" @click="action('legacy-exit-all')" :disabled="busy||!online||!old.connected||!old.trades?.length">旧持仓平仓并暂停</button><button class="primary" @click="action('migrate')" :disabled="busy||!online||!account.connected||migration.blockers?.length>0">空仓核对并应用新策略</button></div><div class="blockers" v-if="migration.blockers?.length"><b>应用前需要完成</b><ul><li v-for="item in migration.blockers">{{item}}</li></ul></div><div v-if="ledgerMismatch" class="alert ledger-diagnostic">交易所当前没有持仓、普通订单或条件单，旧账本仍登记 {{snapshot.legacy_book.open_trades}} 笔未平交易。这是账本待核对，与交易所未完成订单不同；核对完成前不应用新策略。</div><small class="small-note">若存在旧仓，可等待原引擎按保护退出，也可由你点击平仓。提交请求不代表已成交；确认空仓并清理残留订单后才能过渡。原实盘账本和损益记录保留。</small></section>
    <section class="panel"><div class="panel-heading"><h2>行情与接口状态</h2><span class="version">{{streamSummary}}</span></div><p class="small-note">实时成交价、买卖报价和标记价通过WebSocket接收；连接失败后固定每10分钟自动重试，持续尝试直到读取成功。等待采用后台计时，页面和停止操作仍可使用。恢复连接后自动核对实盘数据，并延续此前有效的交易意图；你主动停止的交易保持停止。本分钟请求权重参考计数 {{snapshot?.request_budget?.used_weight??'—'}}；本地常规请求预算 {{snapshot?.request_budget?.read_budget_per_minute??1200}} / 分钟。</p><div class="connection-check-controls"><button class="secondary" data-testid="check-connection" @click="checkConnection" :disabled="checkSubmitting||!online||!newApi">{{checkSubmitting?'正在登记检查…':'立即检查连接'}}</button><p class="small-note">可在十分钟等待期间提前检查。账户接口与行情通道分别核对，健康连接保持连接；交易所要求的限流冷却仍需等待。检查与启动策略分开，主动停止的交易保持停止。</p></div><div v-if="checkNotice" class="alert success" role="status">{{checkNotice}}</div><div v-if="checkError" class="alert danger" role="alert">{{checkError}}</div><div v-if="connectionCheck.id" class="connection-check-result" role="status" aria-live="polite"><strong>{{checkState}}</strong><p>任务 {{connectionCheck.id}} · {{checkStage}}</p><p class="small-note">登记 {{eventTime({time_ms:connectionCheck.requested_at_ms})}}<br>实际开始 {{eventTime({time_ms:connectionCheck.started_at_ms})}}；完成 {{eventTime({time_ms:connectionCheck.completed_at_ms})}}<br>检查截止 {{eventTime({time_ms:connectionCheck.deadline_at_ms})}}</p><p v-if="connectionCheck.reason">{{connectionCheck.reason}}</p><p v-if="connectionCheck.retry_at_ms" class="small-note">下次可执行：{{eventTime({time_ms:connectionCheck.retry_at_ms})}}；约 {{Math.max(0,Math.ceil(Number(connectionCheck.retry_in_seconds)||0))}} 秒后。</p><div v-if="connectionCheck.result" class="small-note">账户接口：{{checkPartLabel(connectionCheck.result.rest)}}<br>买卖报价：{{checkPartLabel(connectionCheck.result.streams?.public)}}；成交与标记价格：{{checkPartLabel(connectionCheck.result.streams?.market)}}<br>未确定订单：{{checkPartLabel(connectionCheck.result.unknown_orders)}}</div><p v-if="connectionCheck.deadline_elapsed&&['accepted','checking','waiting'].includes(connectionCheck.state)" class="small-note">显示的截止时间已到，等待任务所有者确认最终结果；页面不会重发检查或恢复交易。</p></div><p class="small-note">行情显示副本年龄 {{f(displayStream.display_copy_age_seconds??0,1)}} 秒。显示副本过期与实际连接断开分别显示；交易报价的3秒有效期保持不变。</p><div class="small-note" v-for="symbol in symbols">{{symbol}}：报价 {{quoteStatus(symbol,'book')}}；成交 {{quoteStatus(symbol,'trade')}}；标记价 {{quoteStatus(symbol,'mark')}}</div><div v-if="networkRetry.probing" class="alert">正在尝试重新连接币安读取接口；交易状态保持不变。</div><div v-else-if="networkRetry.waiting" class="alert danger">账户接口连接失败，约 {{Math.max(0,Math.ceil(Number(networkRetry.retry_in_seconds)||0))}} 秒后自动重试。固定间隔10分钟，重试次数不限；倒计时每5秒刷新。</div><div v-for="retry in streamRetries" :key="retry.name" class="alert">{{retry.name}}连接已断开，约 {{retry.seconds}} 秒后自动重连。</div><div v-if="snapshot?.request_budget?.cooldown_seconds" class="alert danger">币安接口限流冷却中，约 {{snapshot.request_budget.cooldown_seconds}} 秒后重新核对。交易所要求更长等待时，以交易所期限为准；已有交易所止损继续按交易所规则触发。</div><p v-if="account.stale" class="small-note">账户读取失败，旧数据仅供查看；连接恢复并重新核对前不能启动。{{account.error}}</p></section>
    <section v-if="recovery.pending" class="panel" role="status"><div class="panel-heading"><h2>{{recoveryName}}</h2><span class="version">{{desiredRunning?'恢复后自动继续交易':'用户已停止新开仓'}}</span></div><p>{{recovery.reason||worker.fault_reason||'正在核对执行条件'}}</p><p class="small-note">{{Number(recovery.retry_in_seconds)>0?'约 '+Math.ceil(Number(recovery.retry_in_seconds))+' 秒后再次尝试':'正在处理并核对'}}；已记录 {{recovery.attempts||0}} 次异常。订单状态未确定时先查询原订单，过期信号不补开。</p></section><div v-else-if="worker.fault_reason" class="alert danger">{{worker.fault_reason}}</div>
    <div v-else-if="worker.reconciliation_reason" class="alert danger">{{worker.reconciliation_reason}}；核对期间不允许新开仓。</div>
    <section class="stats strategy-balances"><div v-for="symbol in symbols" :key="symbol" class="stat"><label>{{symbol}}独立策略权益 · USDT</label><strong>{{ledger(symbol).verified?f(ledger(symbol).equity):'待核对'}}</strong><small>{{ledger(symbol).initialized_at_ms?'钱包 '+f(ledger(symbol).wallet)+'；标记价浮盈亏 '+f(ledger(symbol).unrealized):'默认分配100U；可先编辑，不会开启此品种'}}<br>后续新仓计划预算 {{ledger(symbol).verified?f(Number(ledger(symbol).equity)*.5):'—'}}；名义上限 {{ledger(symbol).verified?f(Number(ledger(symbol).equity)*15):'—'}}</small><div class="equity-controls"><button v-if="!equityEdits[symbol].editing" class="text-button" :disabled="!online||!worker.connected" @click="equityEditor.begin(symbol,ledger(symbol))">编辑{{symbol.startsWith('BTC')?'BTC':'ETH'}}策略权益</button><form v-else @submit.prevent="saveEquity(symbol)"><label :for="'equity-'+symbol">将当前策略权益调整为（USDT）</label><input :id="'equity-'+symbol" v-model="equityEdits[symbol].draft" type="text" inputmode="decimal" autocomplete="off" :disabled="equityEdits[symbol].submitting||!!equityEdits[symbol].pending"><div><button class="primary" :disabled="equityEdits[symbol].submitting||!online||!worker.connected">{{equityEdits[symbol].submitting?'核对并保存中…':equityEdits[symbol].pending?'重试原保存':'保存权益'}}</button><button v-if="equityEdits[symbol].pending" type="button" class="secondary" :disabled="equityEdits[symbol].submitting||!online" @click="queryEquity(symbol)">查询保存结果</button><button v-else type="button" class="text-button" :disabled="equityEdits[symbol].submitting" @click="equityEditor.cancel(symbol)">取消</button></div><small>保存为账户核对时的策略权益，之后盈亏继续累计。只调整本地策略账本，不充值或划转；已有持仓的入场预算和止损规则不变。保存后等待该品种新的小时信号。</small><small v-if="equityEdits[symbol].pending">保存编号：{{equityEdits[symbol].pending.operation_id}}</small></form><p v-if="equityEdits[symbol].error" class="negative" role="alert">{{equityEdits[symbol].error}}</p><p v-if="equityEdits[symbol].notice" class="small-note" role="status">{{equityEdits[symbol].notice}}</p><small v-if="ledger(symbol).last_equity_adjustment">上次调整：{{eventTime({time_ms:ledger(symbol).last_equity_adjustment.time_ms})}}，目标 {{ledger(symbol).last_equity_adjustment.target_equity}}U；调整流水版本 {{ledger(symbol).allocation_revision}}</small></div></div></section>
    <section class="stats"><div class="stat"><label>币安标记价账户实际权益 · USDT</label><strong>{{account.connected?f(account.equity_usdt):'—'}}</strong><small>真实钱包余额 + 标记价未实现盈亏</small></div><div class="stat"><label>币安可用保证金 · USDT</label><strong>{{account.connected?f(account.available_usdt):'—'}}</strong><small>入场时额外检查真实可用保证金</small></div><div class="stat"><label>交易所当前普通 / 条件单</label><strong>{{account.connected?account.open_orders:'—'}} / {{account.connected?account.open_algo_orders:'—'}}</strong><small>当前下单条件，不审核旧策略状态</small></div><div class="stat"><label>本策略登记持仓</label><strong>{{worker.connected?(worker.trades||[]).length:'—'}}<em>/ 2</em></strong><small>每品种最多一笔 · BTC / ETH</small></div></section>
    <template v-if="tab==='总览'"><div class="overview-grid"><section class="market-grid"><article v-for="symbol in symbols" class="panel market-card"><div class="market-head"><div :class="['coin',symbol.startsWith('ETH')?'eth':'']">{{symbol.startsWith('BTC')?'₿':'Ξ'}}</div><div><h2>{{symbol.startsWith('BTC')?'BTC':'ETH'}} <span>/ USDT</span></h2><small>永续合约 · 1小时 · 固定50倍</small></div><span class="regime">{{market(symbol).ready?branch(market(symbol).branch):'预热中'}}</span></div><div class="price">{{f(liveQuote(symbol)??market(symbol).price)}} <small>{{liveQuote(symbol)?'实时成交价 · WebSocket':'信号收盘价 · USDT'}}</small></div><svg class="spark" viewBox="0 0 600 130" role="img" :aria-label="symbol+'最近96根完整小时线走势'"><polyline v-if="spark(symbol)" :points="spark(symbol)" fill="none" stroke="currentColor" stroke-width="2.4"/><text v-else x="200" y="70" fill="#8794a8" font-size="14">等待完整小时行情</text></svg><div class="market-footer"><div><label>收盘信号</label><b>{{direction(market(symbol).direction)}}</b></div><div><label>EMA50</label><b>{{f(market(symbol).ema)}}</b></div><div><label>ATR14</label><b>{{f(market(symbol).atr)}}</b></div></div><div class="small-note">ADX14 / RSI14：{{f(market(symbol).adx14)}} / {{f(market(symbol).rsi14)}}<br>EMA12：{{f(market(symbol).ema12)}}<br>布林下 / 中 / 上：{{f(market(symbol).boll_lower)}} / {{f(market(symbol).boll_mid)}} / {{f(market(symbol).boll_upper)}}<br>前12小时通道：{{f(market(symbol).breakout_low)}} — {{f(market(symbol).breakout_high)}}<br>完整小时线：{{market(symbol).candle_count||'—'}}；收盘时间 {{closedTime(market(symbol).closed_at)}}<br>{{market(symbol).error||entryReason(symbol)}}<br>{{market(symbol).preview?'公开行情初始化预览；实际执行以引擎序列为准。':'执行引擎固定锚点序列；每小时信号独立消费。'}}</div></article></section><section class="panel execution"><div class="panel-heading"><h2>新策略自动执行</h2><span class="version">唯一固定策略</span></div><p>使用上方手动选择的品种。数量按50%计划预算、15倍名义上限及交易规则计算；关闭品种不会平掉已有持仓。</p><div class="flow"><div><span>01</span>完整小时行情与指标预热</div><div><span>02</span>已有保护、追踪及分支指标退出</div><div><span>03</span>确认空仓、信号窗口及数量</div><div><span>04</span>市价执行与交易所保护</div></div><button class="primary" @click="action('start')" :disabled="busy||!online||!startReady||running||desiredRunning||!selectedCount">{{busy?'处理中…':running?'新策略正在运行':desiredRunning?'自动交易已启用 · 等待恢复':'启动所选品种实盘交易'}}</button><button class="secondary" @click="action('pause')" :disabled="busy||!online||!newApi||pauseButtonDone">{{pauseButtonDone?'已停止新开仓':'停止全部新开仓'}}</button><button v-if="!migration.required&&!worker.connected&&snapshot?.ledger_available" class="secondary" @click="action('restore')" :disabled="busy||!online">恢复交易进程并核对已保存意图</button><button class="text-button" @click="tab='固定参数'">查看固定参数 →</button><div v-if="blockers.length" class="blockers"><b>启动前需要完成</b><ul><li v-for="item in blockers">{{item}}</li></ul></div></section></div>
    <section class="panel"><div class="panel-heading"><h2>实盘账户持仓</h2><span class="version">币安读取 · 所有策略</span></div><div class="table-wrap"><table><thead><tr><th>合约</th><th>方向</th><th>数量</th><th>入场均价</th><th>未实现盈亏</th></tr></thead><tbody><tr v-for="p in account.positions||[]"><td>{{p.symbol}}</td><td>{{p.side==='BOTH'?(p.quantity>0?'做多':'做空'):p.side==='LONG'?'做多':'做空'}}</td><td>{{f(Math.abs(p.quantity),5)}}</td><td>{{f(p.entry_price)}}</td><td :class="p.unrealized<0?'negative':'positive'">{{f(p.unrealized)}} USDT</td></tr><tr v-if="!(account.positions||[]).length"><td colspan="5" class="empty">{{account.connected?'账户当前没有持仓':'连接后显示真实持仓'}}</td></tr></tbody></table></div><div class="small-note">账户模式：{{account.connected?(account.hedge_mode?'双向':'单向'):'待读取'}} / {{account.connected?(account.multi_asset?'多资产':'单资产'):'待读取'}}；可用保证金 {{f(account.available_usdt)}} USDT；未实现盈亏 {{f(account.unrealized_usdt)}} USDT。</div></section></template>
    <section v-if="tab==='固定参数'" class="panel"><div class="panel-heading"><h2>BTC / ETH 唯一固定策略</h2><span class="version">HourlyTrendRange</span></div><p class="intro">参数按你的新说明固定。原杠杆输入、每笔固定保证金和策略档位已移除。入场时冻结权益及额度，后续部分成交、减仓始终沿用同一组预算。</p><div class="table-wrap"><table class="fixed-table"><thead><tr><th>项目</th><th>固定规则</th></tr></thead><tbody><tr v-for="row in fixedRows"><td>{{row[0]}}</td><td>{{row[1]}}</td></tr></tbody></table></div><div class="small-note">50%为计划止损预算。实际损益和手续费按成交记录记账；未来资金费不进入入场计划预算，实际结算进入权益。</div></section>
    <template v-if="tab==='交易记录'"><section class="panel"><div class="panel-heading"><h2>新小时策略登记记录</h2><button class="text-button" @click="action('exit-all')" :disabled="busy||!online||!worker.connected||!worker.trades?.length">新策略平仓并暂停</button></div><div class="table-wrap"><table><thead><tr><th>编号</th><th>合约</th><th>分支</th><th>方向</th><th>数量</th><th>均价</th><th>有效止损</th><th>预算消耗</th><th>状态</th></tr></thead><tbody><tr v-for="t in worker.history||worker.trades||[]"><td>{{t.trade_id||t.id||'—'}}</td><td>{{t.symbol||t.pair}}</td><td>{{branch(t.branch)}}</td><td>{{direction(t.direction??(t.is_short?-1:1))}}</td><td>{{f(t.quantity??t.q??t.amount,5)}}</td><td>{{f(t.average??t.entry_price??t.avg_price??t.avg)}}</td><td>{{f(t.confirmed_stop??t.stop_price??t.stop)}}</td><td>{{f(t.actual_cost??t.cost_actual??t.consumed_budget??t.cost)}}</td><td>{{t.exit_reason||t.status||t.phase||'持仓中'}}</td></tr><tr v-if="!(worker.history||worker.trades||[]).length"><td colspan="8" class="empty">新策略暂无登记交易。</td></tr></tbody></table></div></section><section v-if="oldPresent||(old.history||[]).length" class="panel"><div class="panel-heading"><h2>旧引擎历史与过渡记录</h2><span class="version">保留账本 · 不作为新策略收益</span></div><div class="table-wrap"><table><thead><tr><th>编号</th><th>品种</th><th>方向</th><th>保证金</th><th>杠杆</th><th>净盈亏</th><th>退出原因</th></tr></thead><tbody><tr v-for="t in old.history||old.trades||[]"><td>{{t.trade_id}}</td><td>{{t.pair}}</td><td>{{t.is_short?'做空':'做多'}}</td><td>{{f(t.stake_amount)}}</td><td>{{t.leverage}}倍</td><td>{{f(t.profit_abs)}}</td><td>{{oldExitReason(t.exit_reason)}}</td></tr></tbody></table></div></section></template>
    <section v-if="tab==='策略说明'" class="panel strategy"><div class="panel-heading"><h2>趋势突破＋震荡回归</h2><a class="text-button" href="/api/strategy-spec" target="_blank">完整新策略说明 →</a></div><div class="strategy-grid"><article><span>01 / 严格突破</span><h3>ADX14划分趋势与震荡</h3><p>ADX≥20用EMA50＋此前12小时严格突破；ADX&lt;20用SMA30±1.5倍总体标准差、RSI14多&lt;45空&gt;55，距中轨/收盘严格&gt;.2%。每笔分支冻结。</p></article><article><span>02 / 一次信号</span><h3>收盘后前5分钟执行</h3><p>新小时边界确认空仓、无未定订单才允许开仓。同一信号最多一次；信号时已有仓位，之后平仓也不反手。价格偏离超过max(0.5%, ATR/收盘价)跳过。</p></article><article><span>03 / 冻结预算</span><h3>50%计划预算与15倍名义上限</h3><p>每品种默认100U独立账本，当前权益可分别调整；预计损失包含开平手续费与不利执行成本，数量向下取整；不符合规则就放弃。成交超限只减仓，不补单、不追加、不放宽止损。</p></article><article><span>04 / 小时追踪</span><h3>5ATR初始、6ATR追踪</h3><p>追踪按交易所首次实际成交时间起算，排除该成交小时，从下一根完整小时线累计。替换保护先确认新单有效，再撤旧单。价格已越过新止损立即市价退出。</p></article><article><span>05 / 执行顺序</span><h3>已有保护 → 追踪 → EMA → 入场</h3><p>STOP_MARKET采用CONTRACT_PRICE、priceProtect=false，价格触发不等小时。趋势持仓多收盘&lt;EMA12、空&gt;EMA12；震荡持仓多收盘&gt;SMA30、空&lt;SMA30。相等不退出，退出意图保持至确认平仓。</p></article><article><span>06 / 异常核对</span><h3>超时查询原订单，禁止盲目补单</h3><p>保护更新失败保留旧保护。无法确认任何有效保护则处理剩余开仓委托、退出已确认持仓；完成成交、费用和真实状态核对后按原启停意图自动继续。重启先核对真实仓位、普通单和条件单。</p></article></div><div class="small-note">旧研究报告和旧收益属于已退役策略，当前页面不将它们作为新策略验证结果。新成交、调整费用和风险偏离均保留记录。</div></section>
    <section class="panel events"><div class="panel-heading"><h2>运行事件</h2><small>版本：{{worker.software_release||'待核对'}} · 最近读取：{{snapshot?.updated_at||'等待读取'}}</small></div><div v-for="e in [...(worker.events||[]),...(snapshot?.events||[])].slice(0,30)" class="event"><time>{{eventTime(e)}}</time><span>{{eventText(e)}}</span></div><div v-if="worker.unknown_orders?.length" class="small-note">存在 {{worker.unknown_orders.length}} 个状态未确定订单，新开仓保持关闭。</div></section><footer>127.0.0.1:8788 · BTC / ETH USDT本位永续 · 币安正式接口</footer>
